<?php
require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/auth.php';require_login();
$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $act=$_POST['action']??'';
 if($act==='create'){
  $eid=(int)($_POST['employee_id']??0);$month=$_POST['pay_month']??'';$allow=(float)($_POST['allowance']??0);$bonus=(float)($_POST['bonus']??0);$ded=(float)($_POST['deduction']??0);$unpaid=max(0,(int)($_POST['unpaid_days']??0));
  if(!$eid||!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month)||min($allow,$bonus,$ded)<0)$error='Enter valid employee, month and non-negative salary components.';
  else{$q=$pdo->prepare('SELECT basic_salary FROM employees WHERE id=?');$q->execute([$eid]);$emp=$q->fetch();
   if(!$emp)$error='Employee not found.';
   else{$basic=(float)$emp['basic_salary'];$unpaidDed=round(($basic/30)*$unpaid,2);$net=$basic+$allow+$bonus-$ded-$unpaidDed;
    if($net<0)$error='Deductions exceed the total salary.';
    else try{$q=$pdo->prepare('INSERT INTO payroll(employee_id,pay_month,basic_salary,allowance,bonus,deduction,unpaid_days,unpaid_deduction,net_salary) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$eid,$month,$basic,$allow,$bonus,$ded,$unpaid,$unpaidDed,$net]);$success='Payroll created.';}catch(PDOException $ex){$error=$ex->getCode()==='23000'?'Payroll already exists for this employee and month.':'Could not create payroll.';}
   }
  }
 }elseif($act==='status'){$s=($_POST['payment_status']??'')==='Paid'?'Paid':'Pending';$q=$pdo->prepare('UPDATE payroll SET payment_status=? WHERE id=?');$q->execute([$s,(int)$_POST['id']]);$success='Payment status updated.';}
 elseif($act==='delete'){$q=$pdo->prepare('DELETE FROM payroll WHERE id=?');$q->execute([(int)$_POST['id']]);$success='Payroll record deleted.';}
}
$employees=$pdo->query('SELECT id,employee_code,full_name,basic_salary FROM employees ORDER BY full_name')->fetchAll();
$rows=$pdo->query('SELECT p.*,e.full_name,e.employee_code FROM payroll p JOIN employees e ON e.id=p.employee_id ORDER BY p.pay_month DESC,p.id DESC')->fetchAll();
$page_title='Payroll | EIPS';require __DIR__.'/includes/header.php';?>
<div class="page-heading"><div><div class="eyebrow">SALARY PROCESSING</div><h1>Payroll processing</h1><p class="muted">Calculate monthly gross pay, deductions and net salary.</p></div></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?>
<div class="two-col payroll-cols"><section class="panel"><div class="panel-heading"><div><h2>Create payroll</h2><p class="muted">Unpaid day deduction uses basic salary ÷ 30.</p></div></div><?php if(!$employees):?><p>Add an employee before payroll.</p><a class="btn primary" href="employees.php">Add employee</a><?php else:?><form method="post" class="form-stack"><input type="hidden" name="action" value="create"><label>Employee *<select name="employee_id" required><option value="">Select employee</option><?php foreach($employees as $e1):?><option value="<?=(int)$e1['id']?>"><?=e($e1['employee_code'].' — '.$e1['full_name'].' ('.money($e1['basic_salary']).')')?></option><?php endforeach;?></select></label><label>Pay month *<input type="month" name="pay_month" value="<?=e(date('Y-m'))?>" required></label><label>Allowance (₹)<input type="number" name="allowance" min="0" step=".01" value="0" required></label><label>Bonus (₹)<input type="number" name="bonus" min="0" step=".01" value="0" required></label><label>Other deductions (₹)<input type="number" name="deduction" min="0" step=".01" value="0" required></label><label>Unpaid days<input type="number" name="unpaid_days" min="0" max="31" value="0" required></label><button class="btn primary">Calculate & save payroll</button></form><?php endif;?></section>
<section class="panel"><div class="panel-heading"><div><h2>Payroll records</h2><p class="muted"><?=count($rows)?> record(s)</p></div></div><?php if(!$rows):?><div class="empty-state"><p>No payroll records yet.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Month</th><th>Net pay</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['full_name'])?></strong><small class="table-sub"><?=e($r['employee_code'])?></small></td><td><?=e($r['pay_month'])?></td><td><?=money($r['net_salary'])?></td><td><span class="status <?=$r['payment_status']==='Paid'?'paid':'pending'?>"><?=e($r['payment_status'])?></span><form method="post" class="status-form"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="payment_status" onchange="this.form.submit()"><option <?=$r['payment_status']==='Pending'?'selected':''?>>Pending</option><option <?=$r['payment_status']==='Paid'?'selected':''?>>Paid</option></select></form></td><td class="actions"><a class="text-link" href="payslip.php?id=<?=(int)$r['id']?>">Payslip</a><form method="post" class="inline-form" onsubmit="return confirm('Delete this payroll record?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="link-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div>
<?php require __DIR__.'/includes/footer.php';?>
